-- Name: ensure_daily_slots(date); Type: FUNCTION; Schema: public; Owner: neondb_owner
--

CREATE FUNCTION public.ensure_daily_slots(target_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  slot_count INTEGER;
  slot_start_time TIMESTAMPTZ;
  slot_end_time TIMESTAMPTZ;
  current_slot_time TIMESTAMPTZ;
  slot_exists BOOLEAN;
BEGIN
  slot_count := 0;
  current_slot_time := target_date + INTERVAL '9 hours'; -- Start at 9 AM
  slot_end_time := target_date + INTERVAL '21 hours'; -- End at 9 PM
  
  WHILE current_slot_time < slot_end_time LOOP
    slot_start_time := current_slot_time;
    current_slot_time := current_slot_time + INTERVAL '30 minutes';
    
    -- Check if slot already exists
    SELECT EXISTS (
      SELECT 1 FROM slots 
      WHERE slot_date = target_date 
        AND start_time = slot_start_time 
        AND trainer_id IS NULL
        AND is_auto_generated = true
    ) INTO slot_exists;
    
    IF NOT slot_exists THEN
        trainer_id, 
        start_time, 
        end_time, 
        slot_date,
        capacity, 
        booked_count, 
        status, 
        is_auto_generated
      ) VALUES (
        NULL, 
        slot_start_time, 
        current_slot_time, 
        target_date,
        1, 
        0, 
        'available', 
        true
      );
      
      slot_count := slot_count + 1;
    END IF;
  END LOOP;
  
  RETURN slot_count;
END;
$$;


ALTER FUNCTION public.ensure_daily_slots(target_date date) OWNER TO neondb_owner;

