--

CREATE FUNCTION public.is_slot_visible(slot_start_time timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Slot is visible if start_time is at least 24 hours from now
  RETURN slot_start_time >= (NOW() + INTERVAL '24 hours');
END;
$$;


